const COMMA_SEPARATOR = ','

interface AgentProfilesEditorProps {
    disabled?: boolean
    onChange: (value: AgentProfile[]) => void
    onValidityChange?: (valid: boolean) => void
    value: AgentProfile[]
}

interface AgentProfileRowProps {
